function downloadBlob(b,name){const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function download(url,name){const r=await api(url),match=r.headers.get('Content-Disposition')?.match(/filename\*=UTF-8''([^;]+)/i);downloadBlob(await r.blob(),match?decodeURIComponent(match[1]):name);}
async function base64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});}
function guard(fn){return async(...args)=>{try{await fn(...args);}catch(e){toast(e.message);console.error(e);}};}
