$('#export-project').onclick=guard(async()=>{await save();await download(`project-export?id=${p.id}`,'theme-project.zip');});let pendingImport=null;
async function finishImport(data,asNew=false){p=await json('project-import','POST',{base64:data,asNew});await loadProjects();await selectProject(p.id);pendingImport=null;$('#import-conflict-dialog').close();toast(asNew?'독립된 새 프로젝트로 가져왔습니다.':'프로젝트를 복원했습니다.');}
$('#import-project').onclick=()=>$('#project-file').click();$('#project-file').onchange=guard(async()=>{const f=$('#project-file').files[0];if(!f)return;await save();const data=await base64(f),info=await json('project-import-check','POST',{base64:data});$('#project-file').value='';if(info.existingId||info.retired&&!info.restorable){$('#open-existing-import').hidden=!info.existingId;pendingImport={data,info};$('#import-conflict-message').textContent=info.retired?'보관함에 같은 프로젝트가 있습니다. 프로젝트 관리에서 복구하거나 독립된 새 프로젝트로 가져오세요.':`${info.name} · ${info.packageId}와 같은 프로젝트 ID 또는 패키지명이 이미 있습니다.`;$('#import-conflict-dialog').showModal();return;}await finishImport(data);});
$('#cancel-import-copy').onclick=()=>{pendingImport=null;$('#import-conflict-dialog').close();};$('#import-conflict-dialog').addEventListener('cancel',()=>pendingImport=null);
$('#open-existing-import').onclick=guard(async()=>{const id=pendingImport?.info.existingId;if(!id)return;pendingImport=null;$('#import-conflict-dialog').close();await loadProjects();await selectProject(id);});
$('#copy-import').onclick=guard(async()=>{if(!pendingImport)return;const button=$('#copy-import');button.disabled=true;try{await finishImport(pendingImport.data,true);}finally{button.disabled=false;}});

for(const id of ['open-keys','manage-key'])$(`#${id}`).onclick=guard(async()=>{await status();$('#key-dialog').showModal();});$('#close-key').onclick=()=>$('#key-dialog').close();
$('#signing-key').onchange=()=>{p.signingKeyId=$('#signing-key').value||null;changed();};
$('#key-form').onsubmit=guard(async e=>{e.preventDefault();$('#create-key').disabled=true;try{const k=await json('keys','POST',{label:$('#key-label').value,password:$('#key-password').value});p.signingKeyId=k.id;$('#key-password').value='';await status();await save();$('#key-dialog').close();toast('제작자 서명키를 생성했습니다. 키 백업을 보관하세요.');}finally{$('#create-key').disabled=false;}});
$('#unlock-key').onclick=guard(async()=>{const k=await json('keys/unlock','POST',{id:$('#key-list').value,password:$('#key-password').value});p.signingKeyId=k.id;$('#key-password').value='';await status();await save();$('#key-dialog').close();toast('서명키 잠금을 해제했습니다.');});
$('#key-list').onchange=()=>{$('#key-fingerprint').textContent=keys.find(k=>k.id===$('#key-list').value)?.fingerprint??'';};
$('#backup-key').onclick=guard(async()=>{const id=$('#key-list').value||p.signingKeyId;if(!id)throw new Error('백업할 키를 선택하세요.');await download(`keys/backup?id=${id}`,'theme-author-key.p12');});$('#import-key').onclick=()=>$('#key-file').click();$('#key-file').onchange=guard(async()=>{const f=$('#key-file').files[0];if(!f)return;const k=await json('keys/import','POST',{label:$('#key-label').value,password:$('#key-password').value,base64:await base64(f)});p.signingKeyId=k.id;$('#key-password').value='';await status();await save();$('#key-dialog').close();toast('서명키를 복원했습니다.');});
$('#build').onclick=guard(build);$('#capture').onclick=()=>{const canvas=document.createElement('canvas');canvas.width=828;canvas.height=828;const ctx=canvas.getContext('2d');ctx.fillStyle='#f4f6ef';ctx.fillRect(0,0,828,828);text(ctx,'iOS · 예상 화면',24,25,14,'#344c36');text(ctx,'Android · 예상 화면',438,25,14,'#344c36');ctx.drawImage($('#ios-preview'),12,40);ctx.drawImage($('#android-preview'),426,40);canvas.toBlob(b=>downloadBlob(b,'theme-preview.png'));};
const catalogEditor=createCatalogEditor({slotLabel:slot=>slotLabels[slot]??slot,json,api,getProject:()=>p,getPreview:()=>preview,edit:(fn,group)=>{fn(p);changed(group);},focusCommon,focusColor:async id=>{if($('#catalog-dialog').open)$('#catalog-dialog').close();const spec=COMMON_COLORS.find(s=>s.id===id);await selectScreen(spec.screens.includes(screen)?screen:spec.screens[0]);await navigateTarget({platform:'ios',property:spec.ios[0],label:spec.label});},replace:next=>{if(next.id!==p.id)return;p.assets=next.assets;p.assetHashes=next.assetHashes;p.bubbleDesign=next.bubbleDesign;p.bubblePlatforms=next.bubblePlatforms;p.overrides=next.overrides;p.resourceOverrides=next.resourceOverrides;p.nativeNinePatch=next.nativeNinePatch;fields();changed();catalogEditor.refresh();},save,toast,download,base64});
$('#open-catalog').onclick=()=>catalogEditor.open();
for(const spec of SCREENS){const b=document.createElement('button');b.dataset.editScreen=spec.id;b.textContent=spec.title;b.onclick=guard(()=>selectScreen(spec.id));$('#screen-navigation').append(b);}
$('#previous-screen').onclick=guard(()=>selectScreen(SCREENS[(SCREENS.findIndex(x=>x.id===screen)+SCREENS.length-1)%SCREENS.length].id));$('#next-screen').onclick=guard(()=>selectScreen(SCREENS[(SCREENS.findIndex(x=>x.id===screen)+1)%SCREENS.length].id));
const commonColorHost=document.createElement('section');commonColorHost.id='screen-colors';$('#screen-sources').before(commonColorHost);
const designHost=document.createElement('div');designHost.id='bubble-design-controls';$('#screen-bubble').append(designHost);$('#screen-sources').before($('#screen-bubble'));const legacyGeometry=document.createElement('details');legacyGeometry.id='shared-bubble-geometry';legacyGeometry.open=true;const legacyTitle=document.createElement('summary');legacyTitle.textContent='공통 모서리·내용 여백·늘림';legacyGeometry.append(legacyTitle,$('#bubble-controls'));$('#screen-bubble').append(legacyGeometry);$('#screen-bubble').prepend(Object.assign(document.createElement('h3'),{textContent:'말풍선 본체와 캐릭터'}));$('#screen-bubble').append(Object.assign(document.createElement('p'),{className:'muted',textContent:'개별 늘림·여백과 원본 9-patch가 설정되어 있으면 공통 정책보다 우선합니다. 이미지 탭에서 적용 가이드를 확인하세요.'}));
const commonSearch=document.createElement('input');commonSearch.id='common-search';commonSearch.placeholder='공통 리소스 찾기 · 배경, 말풍선, 탭…';commonSearch.setAttribute('aria-label','공통 리소스 찾기');commonSearch.oninput=()=>$('#screen-assets').querySelectorAll('[data-common-slot]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(commonSearch.value.toLowerCase()));$('#screen-assets').before(commonSearch);
$('#screen-passcode').append($('#pattern-preview').closest('label'),$('#passcode-controls'),$('#lock-resource-details'));
$('#lock-resource-details').onclick=()=>catalogEditor.open({tab:'resources',group:'잠금화면'});$('#pattern-preview').onchange=render;
async function moveHistory(direction){if(!projectHistory||historyMoving)return;historyMoving=true;historyButtons();$('#save-status').textContent='저장 중…';$('#preview-status').textContent='변경한 디자인을 반영하고 있습니다…';try{const key=p.signingKeyId;p=direction==='undo'?projectHistory.undo():projectHistory.redo();p.signingKeyId=key;fields();previewSeq++;previewSchedule.cancel();await save();await refreshPreview();await catalogEditor.refresh();}finally{historyMoving=false;historyButtons();}}
$('#undo').onclick=guard(()=>moveHistory('undo'));$('#redo').onclick=guard(()=>moveHistory('redo'));
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'&&!$('#key-dialog').open&&!$('#new-project-dialog').open&&!$('#asset-cleanup-dialog').open&&!$('#project-manager-dialog').open){e.preventDefault();guard(()=>moveHistory(e.shiftKey?'redo':'undo'))();}});
$('#duplicate-project').onclick=guard(async()=>{await save();p=await json('project-clone','POST',{project:p});await loadProjects();await selectProject(p.id);toast('새 앱 ID로 테마를 복제했습니다.');});
function setEmptyProjects(empty){document.body.classList.toggle('no-projects',empty);for(const id of ['theme-name','duplicate-project','export-project','build'])$('#'+id).disabled=empty;if(empty){clearTimeout(saveTimer);previewSeq++;previewSchedule.cancel();preview=null;for(const image of Object.values(images))image.close();images={};p=null;projectHistory=null;historyButtons();$('#theme-name').value='';$('#save-status').textContent='프로젝트를 선택하세요.';}}
async function managedProjectsChanged({kind,id}){await loadProjects();if(!p||!projects.some(item=>item.id===p.id)){if(projects.length)await selectProject(projects[0].id);else setEmptyProjects(true);}else if(kind==='rename'&&id===p.id){p.name=projects.find(item=>item.id===id).name;projectHistory.record(p);fields();historyButtons();}}
const projectManager=createProjectManager({json,save,current:()=>p,onChange:managedProjectsChanged,onOpen:async id=>{await save();await loadProjects();await selectProject(id);},onClone:async id=>{const source=(await json('projects')).find(item=>item.id===id);await json('project-clone','POST',{project:source});await loadProjects();toast('프로젝트를 복제했습니다.');},onBackup:id=>download('project-export?id='+id,'theme-project.zip'),toast});
$('#manage-projects').onclick=()=>projectManager.open();for(const b of $$('[data-empty-create]'))b.onclick=()=>$('#new-project').click();for(const b of $$('[data-empty-import]'))b.onclick=()=>$('#import-project').click();for(const b of $$('[data-empty-manage]'))b.onclick=()=>projectManager.open();
const assetCleanup=createAssetCleanup({json,api,project:()=>p,payload:assetHistoryPayload,save,toast,onChange:refreshProjectStorage});
for(const button of $$('[data-asset-cleanup]'))button.onclick=()=>assetCleanup.open(button.dataset.assetCleanup);
window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message??'요청에 실패했습니다.');});
guard(async()=>{if(!token)throw new Error('실행 터미널 또는 Studio.command에서 인증 링크로 열어 주세요.');await status();await loadProjects();if(!projects.length&&!(await json('project-management')).hasRemovedProjects){p=await json('projects','POST',{name:'이끼 숲'});await loadProjects();}await loadCommonCatalog();if(projects.length){await selectProject(projects[0].id);await selectScreen(screen);}else setEmptyProjects(true);})();
